contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function taking values for setL1BlockValues
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        require(true);

        // Read all observable public fields before the call
        uint64 before_number = c.number();
        uint64 before_timestamp = c.timestamp();
        uint256 before_basefee = c.basefee();
        bytes32 before_hash = c.hash();
        uint64 before_sequenceNumber = c.sequenceNumber();
        bytes32 before_batcherHash = c.batcherHash();
        uint256 before_l1FeeOverhead = c.l1FeeOverhead();
        uint256 before_l1FeeScalar = c.l1FeeScalar();
        address depositor = c.depositorAccount();

        // Attempt to call setL1BlockValues from this contract (msg.sender = InvMutTest)
        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read all observable public fields after the call
        uint64 after_number = c.number();
        uint64 after_timestamp = c.timestamp();
        uint256 after_basefee = c.basefee();
        bytes32 after_hash = c.hash();
        uint64 after_sequenceNumber = c.sequenceNumber();
        bytes32 after_batcherHash = c.batcherHash();
        uint256 after_l1FeeOverhead = c.l1FeeOverhead();
        uint256 after_l1FeeScalar = c.l1FeeScalar();

        // General rule: if this contract is not the depositor account, the call must revert and no observable field may change.
        // If this contract equals depositor, the call may succeed (we don't assert success in that case).
        assert(
            (address(this) == depositor) || (
                reverted
                && after_number == before_number
                && after_timestamp == before_timestamp
                && after_basefee == before_basefee
                && after_hash == before_hash
                && after_sequenceNumber == before_sequenceNumber
                && after_batcherHash == before_batcherHash
                && after_l1FeeOverhead == before_l1FeeOverhead
                && after_l1FeeScalar == before_l1FeeScalar
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function taking values for setL1BlockValues
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        require(true);

        // Observe depositorAccount as reported by the contract
        address depositor = c.depositorAccount();

        // Read all observable public fields before the call
        uint64 before_number = c.number();
        uint64 before_timestamp = c.timestamp();
        uint256 before_basefee = c.basefee();
        bytes32 before_hash = c.hash();
        uint64 before_sequenceNumber = c.sequenceNumber();
        bytes32 before_batcherHash = c.batcherHash();
        uint256 before_l1FeeOverhead = c.l1FeeOverhead();
        uint256 before_l1FeeScalar = c.l1FeeScalar();

        // Attempt to call setL1BlockValues from this contract (msg.sender = InvMutTest)
        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read all observable public fields after the call
        uint64 after_number = c.number();
        uint64 after_timestamp = c.timestamp();
        uint256 after_basefee = c.basefee();
        bytes32 after_hash = c.hash();
        uint64 after_sequenceNumber = c.sequenceNumber();
        bytes32 after_batcherHash = c.batcherHash();
        uint256 after_l1FeeOverhead = c.l1FeeOverhead();
        uint256 after_l1FeeScalar = c.l1FeeScalar();

        // General rule:
        // - If this test contract is the depositor (address(this) == depositor), the call must NOT revert
        //   and the contract's public L1 fields must equal the provided arguments.
        // - If this test contract is NOT the depositor, then either the call reverted, or none of the
        //   public L1 fields changed.
        assert(
            (address(this) == depositor && !reverted
                && after_number == _number
                && after_timestamp == _timestamp
                && after_basefee == _basefee
                && after_hash == _hash
                && after_sequenceNumber == _sequenceNumber
                && after_batcherHash == _batcherHash
                && after_l1FeeOverhead == _l1FeeOverhead
                && after_l1FeeScalar == _l1FeeScalar)
            || (address(this) != depositor
                && (reverted
                    || (
                        after_number == before_number
                        && after_timestamp == before_timestamp
                        && after_basefee == before_basefee
                        && after_hash == before_hash
                        && after_sequenceNumber == before_sequenceNumber
                        && after_batcherHash == before_batcherHash
                        && after_l1FeeOverhead == before_l1FeeOverhead
                        && after_l1FeeScalar == before_l1FeeScalar
                    )
                )
            )
        );
    }

    receive() external payable {}
}
